package br.com.sussmartcare.notification.domain; import jakarta.persistence.*; import java.util.*; @Entity @Table(name="notification_preferences") public class NotificationPreference{@Id private UUID patientId;@Column(nullable=false)private boolean hasSmartphone;@Column(nullable=false)private String preferredChannel;private String fallbackChannel;protected NotificationPreference(){}public NotificationPreference(UUID p,boolean h,String pc,String fc){patientId=p;hasSmartphone=h;preferredChannel=pc;fallbackChannel=fc;}public UUID getPatientId(){return patientId;}public boolean isHasSmartphone(){return hasSmartphone;}public String getPreferredChannel(){return preferredChannel;}public String getFallbackChannel(){return fallbackChannel;}}
